contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call c.Put with some unlockTime and send some ether amount.
    // Ensure this contract has enough balance to send `amt`.
    function run(uint _unlockTime, uint amt) public payable {
        require(address(this).balance >= amt);
        // read balance of Acc for this contract (msg.sender in c will be this test contract)
        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));

        bool reverted;
        // call Put with value amt
        try c.Put{value: amt}(_unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));
        uint cBal = address(c).balance;

        // If the call reverted, nothing in c should have changed (observably): balances and unlockTime remain same and contract balance unchanged.
        // If it did not revert, then afterBalance == beforeBalance + amt and contract balance increased by amt.
        assert(reverted
               ? (afterBalance == beforeBalance && afterUnlockTime == beforeUnlockTime && cBal >= beforeBalance + 0 /* no-change: observable cBal unchanged relative to beforeBalance not directly accessible */)
               : (afterBalance == beforeBalance + amt && afterUnlockTime >= beforeUnlockTime && cBal >= beforeBalance + amt));
    }

    // allow receiving ETH so this contract can fund calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test Collect behavior. Parameters:
    //  _am : amount to attempt to collect from c (in wei)
    //  fund : amount to first deposit into c via Put so there is some balance to collect from
    // This function is payable so the checker can send ETH to fund this contract.
    function run(uint _am, uint fund) public payable {
        require(address(this).balance >= fund);

        // First, deposit `fund` into c under this contract's holder account by calling Put.
        // Use unlockTime = 0 so fallback/Put will set unlockTime to block.timestamp.
        c.Put{value: fund}(0);

        // Read observable before-values
        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        // Try Collect and record whether it reverted.
        bool reverted;
        try c.Collect{value:0}(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // General rule enforced as a single assert:
        // - If Collect reverted, nothing observable changed in Acc for this holder and contract balance unchanged.
        // - If Collect did not revert, then: beforeBalance >= _am, block.timestamp > beforeUnlockTime must have held (these are internal preconditions but we capture observable consequences),
        //   and afterBalance == beforeBalance - _am, and cBalAfter + _am <= cBalBefore (contract balance decreased by at least _am).
        assert(
            reverted
            ? (afterBalance == beforeBalance && afterUnlockTime == beforeUnlockTime && cBalAfter == cBalBefore)
            : (beforeBalance >= _am && afterBalance == beforeBalance - _am && cBalBefore >= cBalAfter && (cBalBefore - cBalAfter) >= _am)
        );
    }

    // allow receiving ETH so this contract can fund calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Parameters:
    //  fund: amount (wei) to deposit via Put so there is some balance to collect from
    //  collectAmt: amount (wei) to attempt to Collect
    function run(uint fund, uint collectAmt) public payable {
        require(address(this).balance >= fund);

        // Deposit `fund` under this contract's holder by calling Put (unlockTime = 0 -> sets to block.timestamp)
        c.Put{value: fund}(0);

        // Read observable before-values for this holder
        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        // Attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect{value:0}(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable after-values
        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // Assert the general rule:
        // - If Collect reverted: holder entry and contract balance unchanged.
        // - If Collect succeeded: holder's stored balance decreased exactly by collectAmt,
        //   and contract balance decreased by at least collectAmt.
        assert(
            reverted
            ? (afterBalance == beforeBalance && afterUnlockTime == beforeUnlockTime && cBalAfter == cBalBefore)
            : (afterBalance + collectAmt == beforeBalance && cBalBefore >= cBalAfter && (cBalBefore - cBalAfter) >= collectAmt)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Parameters:
    // amount: wei to send to Put (or via fallback by using putViaFallback flag)
    // unlockTime: parameter for Put
    // putViaFallback: if true, call fallback() by sending ether with a non-Put call (use try on payable call to address(c))
    function run(uint amount, uint unlockTime, bool putViaFallback) public payable {
        require(address(this).balance >= amount);

        // Read observables before the deposit
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        // Perform the deposit either by Put or by triggering fallback which calls Put(0)
        bool putReverted;
        if (!putViaFallback) {
            try c.Put{value: amount}(unlockTime) {
                putReverted = false;
            } catch {
                putReverted = true;
            }
        } else {
            // Call fallback by sending ether directly to c without using Put signature
            // Use low-level call to trigger fallback: address(c).call{value: amount}("")
            (bool ok,) = address(c).call{value: amount}("\x00");
            // Some callers may send non-empty data; use ok as revert indicator
            putReverted = !ok;
        }

        // Read observables after the deposit attempt
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // Assert general rule:
        // If Put/fallback reverted then nothing observable on storage or contract balance changed.
        // If it succeeded then stored balance did not decrease (afterBal >= beforeBal) and
        // contract balance increased by at least amount (cBalAfter >= cBalBefore + (putReverted ? 0 : amount)).
        assert(
            putReverted
            ? (afterBal == beforeBal && afterUnlock == beforeUnlock && cBalAfter == cBalBefore)
            : (afterBal >= beforeBal && cBalAfter >= cBalBefore + amount)
        );
    }

    // allow receiving ETH if Collect sends funds to this test contract
    receive() external payable {}
}

