contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run simulates: first Put some ether with an unlockTime in future, then attempt Collect of amt.
    // Params:
    //  putAmt - amount of wei to send to Put
    //  unlockOffset - seconds to add to current block.timestamp to set unlockTime (0 means use block.timestamp)
    //  collectAmt - amount requested to Collect
    function run(uint putAmt, uint unlockOffset, uint collectAmt) public payable {
        // we will send putAmt to c via Put. Ensure this contract has enough balance to forward putAmt.
        require(address(this).balance >= putAmt, "insufficient balance for Put");

        // record c's balance before operations
        uint cBalBefore = address(c).balance;

        // Call Put with specified unlock time
        uint unlockTime = block.timestamp + unlockOffset;
        c.Put{value: putAmt}(unlockTime);

        // read stored holder info for this test contract (msg.sender inside c is this contract)
        (uint accUnlockTimeAfter, uint accBalanceAfter) = c.Acc(address(this));

        // Ensure the recorded balance increased by putAmt (this must hold because Put adds msg.value)
        // But Put sets unlockTime to max(_unlockTime, block.timestamp) so expect accUnlockTimeAfter >= block.timestamp
        // Now attempt Collect of collectAmt. Must ensure we have enough gas and sendter pays nothing extra.
        // Save balances before Collect
        uint cBalMid = address(c).balance;
        uint testBalBefore = address(this).balance;

        bool collectReverted;
        // perform Collect in try/catch to capture revert
        try c.Collect{value:0}(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        uint cBalAfter = address(c).balance;
        uint testBalAfter = address(this).balance;
        (uint accUnlockTimeFinal, uint accBalanceFinal) = c.Acc(address(this));

        // Now assert the invariant capturing both successful and unsuccessful Collect behaviors:
        // If Collect did not revert and conditions for transfer were met (i.e., prior stored balance >= MinSum, prior stored balance >= collectAmt, and block.timestamp > prior unlockTime)
        // then Acc.balance must have decreased by exactly collectAmt and contract balance decreased by exactly collectAmt and test contract balance increased by collectAmt.
        // Otherwise, Acc.balance and balances must be unchanged (i.e., collect had no effect).

        // Read MinSum from c
        uint minSum = c.MinSum();

        // We must use the values as observed just after Put (accUnlockTimeAfter, accBalanceAfter) as the "prior" state for Collect.
        bool conditionsForCollect = (accBalanceAfter >= minSum) && (accBalanceAfter >= collectAmt) && (block.timestamp > accUnlockTimeAfter);

        // Build expected relations
        if (!collectReverted) {
            // If it didn't revert, then either it succeeded in sending (and updated state) OR the contract's Collect implementation might still not send (but in P it reverts if send fails).
            // We assert that if conditionsForCollect were true then balances changed by collectAmt, otherwise balances remained unchanged.
            if (conditionsForCollect) {
                assert(accBalanceFinal + collectAmt == accBalanceAfter && cBalAfter + collectAmt == cBalMid && testBalAfter == testBalBefore + collectAmt);
            } else {
                assert(accBalanceFinal == accBalanceAfter && cBalAfter == cBalMid && testBalAfter == testBalBefore);
            }
        } else {
            // If it reverted, no state change must have happened (Collect is all-or-nothing)
            assert(accBalanceFinal == accBalanceAfter && cBalAfter == cBalMid && testBalAfter == testBalBefore);
        }
    }

    // Allow receiving refunds from c if Collect sends Ether to this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: putAmt sent to Put, unlockOffset added to now for unlockTime, collectAmt requested to Collect
    function run(uint putAmt, uint unlockOffset, uint collectAmt) public payable {
        require(address(this).balance >= putAmt, "insufficient balance for Put");

        // Observe balances before Put
        uint cBalBefore = address(c).balance;
        uint selfBalBefore = address(this).balance;

        // Call Put as a top-level state-changing call
        uint unlockTime = block.timestamp + unlockOffset;
        c.Put{value: putAmt}(unlockTime);

        // Read holder state after Put (these are public getters)
        (uint accUnlockAfter, uint accBalAfter) = c.Acc(address(this));

        // Capture balances before Collect
        uint cBalMid = address(c).balance;
        uint selfBalMid = address(this).balance;

        // Perform Collect as a top-level call and capture whether it reverted
        bool collectReverted;
        try c.Collect{value:0}(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read final states
        uint cBalFinal = address(c).balance;
        uint selfBalFinal = address(this).balance;
        (uint accUnlockFinal, uint accBalFinal) = c.Acc(address(this));
        uint minSum = c.MinSum();

        // Build the general invariant as a single assert:
        // If Collect reverted -> no change to holder balance or contract/self balances between mid and final.
        // If Collect did not revert and the pre-Collect conditions held (accBalAfter >= minSum, accBalAfter >= collectAmt, block.timestamp > accUnlockAfter)
        // then holder balance decreased by collectAmt, contract balance decreased by collectAmt, and this contract's balance increased by collectAmt.
        // Otherwise (didn't revert but conditions false) no balances changed.

        bool preCond = (accBalAfter >= minSum) && (accBalAfter >= collectAmt) && (block.timestamp > accUnlockAfter);

        assert(
            (collectReverted && accBalFinal == accBalAfter && cBalFinal == cBalMid && selfBalFinal == selfBalMid)
            ||
            (!collectReverted && preCond && accBalFinal + collectAmt == accBalAfter && cBalFinal + collectAmt == cBalMid && selfBalFinal == selfBalMid + collectAmt)
            ||
            (!collectReverted && !preCond && accBalFinal == accBalAfter && cBalFinal == cBalMid && selfBalFinal == selfBalMid)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: putAmt is Ether to send with Put, unlockTime is the argument to Put
    function run(uint putAmt, uint unlockTime) public payable {
        require(address(this).balance >= putAmt, "insufficient balance to send Put");

        // Read recorded balance before Put for this test contract's holder
        (uint unlockBefore, uint balBefore) = c.Acc(address(this));

        // Call Put as a top-level state-changing call, sending putAmt wei
        c.Put{value: putAmt}(unlockTime);

        // Read recorded balance after Put
        (uint unlockAfter, uint balAfter) = c.Acc(address(this));

        // General invariant: the recorded balance after Put is >= recorded balance before Put
        // and increased by at least the sent amount (no decrease, and at least putAmt added).
        // Note: Put can set unlockTime to max(_unlockTime, block.timestamp) but must not reduce balance.
        assert(balAfter >= balBefore && balAfter >= balBefore + putAmt - 0);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // putAmt - amount of wei to send with Put
    // unlockTime - parameter passed to Put
    function run(uint putAmt, uint unlockTime) public payable {
        // must have funds to send
        require(address(this).balance >= putAmt, "insufficient balance for Put");

        // read observable state before
        (uint uBefore, uint balBefore) = c.Acc(address(this));
        uint contractBalBefore = address(c).balance;

        // perform Put and capture whether it reverted
        bool reverted;
        try c.Put{value: putAmt}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observable state after
        (uint uAfter, uint balAfter) = c.Acc(address(this));
        uint contractBalAfter = address(c).balance;

        // General rule:
        // If Put reverted, nothing is required about balances here (call had no effect from this tx perspective).
        // If Put did not revert, then (1) the contract's balance must have increased by exactly putAmt,
        // and (2) the recorded holder balance for this address must be >= previous holder balance + putAmt.
        assert(reverted || (contractBalAfter == contractBalBefore + putAmt && balAfter >= balBefore + putAmt));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // putAmt - amount used to fund a prior Put (so there is something to collect)
    // unlockTime - unlock time for that Put
    // collectAmt - amount to attempt to Collect
    function run(uint putAmt, uint unlockTime, uint collectAmt) public payable {
        // ensure this test contract has funds to call Put
        require(address(this).balance >= putAmt, "insufficient balance for Put");

        // perform a Put to set up a nonzero holder balance (may revert)
        bool putReverted;
        try c.Put{value: putAmt}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // observe before-Collect public state for this holder
        (uint uBefore, uint balBefore) = c.Acc(address(this));
        uint contractBalBefore = address(c).balance;

        // attempt Collect and record whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // observe after-Collect public state for this holder
        (uint uAfter, uint balAfter) = c.Acc(address(this));
        uint contractBalAfter = address(c).balance;

        // General rule:
        // Collect must not increase the recorded holder balance nor the contract's Ether balance.
        // (Put may have failed; the rule must hold regardless of prior revert.)
        assert(balAfter <= balBefore && contractBalAfter <= contractBalBefore);
    }

    receive() external payable { }
}

